import re
from typing import List, Dict, Optional

def entities(doc, scope) -> List[Dict[str, str]]:
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    children_nodes = [node_by_id(doc, cid) for cid in scope_node.get("children", [])]
    objects_node = None
    for node in children_nodes:
        if node.get("kind") == "list" and ": Objects" in node.get("title", ""):
            objects_node = node
            break

    if not objects_node:
        return []

    result = []
    lines = objects_node.get("lines", [])
    for line_idx, line in enumerate(lines):
        match = re.match(r"Object (\d+):\s*(.+)", line)
        if match:
            obj_id = f"Object {match.group(1)}"
            result.append({
                "id": obj_id,
                "description": line
            })
    return result

def recorded_end(doc, scope) -> Optional[float]:
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None

    children_nodes = [node_by_id(doc, cid) for cid in scope_node.get("children", [])]

    max_frame = -1
    found_any = False

    motion_node = None
    events_node = None
    for node in children_nodes:
        title = node.get("title", "")
        if ": Motion log" in title:
            motion_node = node
        elif ": Events" in title:
            events_node = node

    if motion_node and motion_node.get("kind") == "table":
        rows = table_rows(motion_node)
        for row_idx, row_data in rows:
            frame_str = row_data.get("frame", "")
            try:
                frame = float(frame_str)
                if frame > max_frame:
                    max_frame = frame
                found_any = True
            except ValueError:
                pass

    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for line in lines:
            match = re.match(r"Frame (\d+):", line)
            if match:
                frame = float(match.group(1))
                if frame > max_frame:
                    max_frame = frame
                found_any = True

    return max_frame if found_any else None

def inputs(doc, scope) -> List[Dict]:
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    children_nodes = [node_by_id(doc, cid) for cid in scope_node.get("children", [])]

    objects_node = None
    events_node = None
    motion_node = None

    for node in children_nodes:
        title = node.get("title", "")
        if ": Objects" in title:
            objects_node = node
        elif ": Events" in title:
            events_node = node
        elif ": Motion log" in title:
            motion_node = node

    inputs_list = []

    # 1. Object Properties
    if objects_node and objects_node.get("kind") == "list":
        lines = objects_node.get("lines", [])
        for line_idx, line in enumerate(lines):
            match = re.match(r"Object (\d+):\s*(.+)", line)
            if match:
                obj_id = f"Object {match.group(1)}"
                fields = {}
                for m in re.finditer(r'(\w+)=(\w+)', match.group(2)):
                    fields[m.group(1)] = m.group(2)

                inputs_list.append({
                    "id": f"prop_{obj_id}",
                    "time": None,
                    "kind": "Object Properties",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": [[objects_node.get("node_id"), line_idx]]
                })

    # 2. Entries and Initial Views from Events
    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for line_idx, line in enumerate(lines):
            match = re.match(r"Frame (\d+):\s*Object (\d+).*?(enters the scene|is in view when the video begins)", line)
            if match:
                frame = float(match.group(1))
                obj_id = f"Object {match.group(2)}"
                event_type = match.group(3)
                inputs_list.append({
                    "id": f"entry_{obj_id}_{int(frame)}",
                    "time": frame,
                    "kind": "Entry" if "enters" in event_type else "Initial View",
                    "entities": [obj_id],
                    "fields": {"event": event_type},
                    "src": [[events_node.get("node_id"), line_idx]]
                })

    # 3. Initial States from Motion Log (frame 0)
    if motion_node and motion_node.get("kind") == "table":
        rows = table_rows(motion_node)
        for row_idx, row_data in rows:
            frame_val = float(row_data.get("frame", "-1"))
            if frame_val == 0:
                obj_col = row_data.get("object", "")
                obj_match = re.match(r"(\d+)", obj_col)
                if obj_match:
                    obj_id = f"Object {obj_match.group(1)}"
                    fields = {}
                    for col in ['x', 'y', 'vx', 'vy', 'speed']:
                        val = row_data.get(col, "")
                        try:
                            fields[col] = float(val)
                        except ValueError:
                            pass
                    inputs_list.append({
                        "id": f"init_state_{obj_id}",
                        "time": 0.0,
                        "kind": "Initial State",
                        "entities": [obj_id],
                        "fields": fields,
                        "src": [[motion_node.get("node_id"), row_idx]]
                    })

    return inputs_list

def outcomes(doc, scope) -> List[Dict]:
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    children_nodes = [node_by_id(doc, cid) for cid in scope_node.get("children", [])]
    events_node = None
    for node in children_nodes:
        if ": Events" in node.get("title", ""):
            events_node = node
            break

    outcomes_list = []

    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for line_idx, line in enumerate(lines):
            # Collision
            col_match = re.match(r"Frame (\d+):\s*(Object \d+).*collides with (Object \d+)", line)
            if col_match:
                outcomes_list.append({
                    "time": float(col_match.group(1)),
                    "kind": "Collision",
                    "entities": [col_match.group(2), col_match.group(3)],
                    "value": None,
                    "src": [[events_node.get("node_id"), line_idx]]
                })
                continue

            # Exit
            exit_match = re.match(r"Frame (\d+):\s*(Object \d+).*exits the scene", line)
            if exit_match:
                outcomes_list.append({
                    "time": float(exit_match.group(1)),
                    "kind": "Exit",
                    "entities": [exit_match.group(2)],
                    "value": None,
                    "src": [[events_node.get("node_id"), line_idx]]
                })
                continue

    return outcomes_list

def params(doc, scope) -> Dict[str, float]:
